CREATE OR REPLACE FUNCTION scenegen_territory_matches(territory TEXT, country TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
DECLARE
  territory_key TEXT := lower(trim(COALESCE(territory, '')));
  country_key TEXT := scenegen_country_key(country);
BEGIN
  IF territory_key NOT LIKE '@region:%' THEN
    RETURN scenegen_country_key(territory) = country_key;
  END IF;
  IF territory_key = '@region:europe' THEN
    RETURN country_key = ANY(ARRAY['ALBANIA','ANDORRA','AUSTRIA','BELARUS','BELGIUM','BOSNIAANDHERZEGOVINA','BULGARIA','CROATIA','CYPRUS','CZECHREPUBLIC','DENMARK','ESTONIA','FINLAND','FRANCE','GERMANY','GREECE','HUNGARY','ICELAND','IRELAND','ITALY','KOSOVO','LATVIA','LIECHTENSTEIN','LITHUANIA','LUXEMBOURG','MALTA','MOLDOVA','MONACO','MONTENEGRO','NETHERLANDS','NORTHMACEDONIA','NORWAY','POLAND','PORTUGAL','ROMANIA','RUSSIA','SANMARINO','SERBIA','SLOVAKIA','SLOVENIA','SPAIN','SWEDEN','SWITZERLAND','UKRAINE','VATICANCITY']);
  ELSIF territory_key = '@region:asia' THEN
    RETURN country_key = ANY(ARRAY['AFGHANISTAN','ARMENIA','AZERBAIJAN','BAHRAIN','BANGLADESH','BHUTAN','BRUNEI','CAMBODIA','CHINA','GEORGIA','INDIA','INDONESIA','IRAN','IRAQ','ISRAEL','JAPAN','JORDAN','KAZAKHSTAN','KUWAIT','KYRGYZSTAN','LAOS','LEBANON','MALAYSIA','MALDIVES','MONGOLIA','MYANMAR','NEPAL','NORTHKOREA','OMAN','PAKISTAN','PALESTINE','PHILIPPINES','QATAR','SAUDIARABIA','SINGAPORE','SOUTHKOREA','SRILANKA','SYRIA','TAIWAN','TAJIKISTAN','THAILAND','TIMORLESTE','TURKEY','TURKMENISTAN','UNITEDARABEMIRATES','UZBEKISTAN','VIETNAM','YEMEN']);
  ELSIF territory_key = '@region:africa' THEN
    RETURN country_key = ANY(ARRAY['ALGERIA','ANGOLA','BENIN','BOTSWANA','BURKINAFASO','BURUNDI','CABOVERDE','CAMEROON','CENTRALAFRICANREPUBLIC','CHAD','COMOROS','CONGODRC','CONGOREPUBLIC','DJIBOUTI','EGYPT','EQUATORIALGUINEA','ERITREA','ESWATINI','ETHIOPIA','GABON','GAMBIA','GHANA','GUINEA','GUINEABISSAU','IVORYCOAST','KENYA','LESOTHO','LIBERIA','LIBYA','MADAGASCAR','MALAWI','MALI','MAURITANIA','MAURITIUS','MOROCCO','MOZAMBIQUE','NAMIBIA','NIGER','NIGERIA','RWANDA','SAOTOMEANDPRINCIPE','SENEGAL','SEYCHELLES','SIERRALEONE','SOMALIA','SOUTHAFRICA','SOUTHSUDAN','SUDAN','TANZANIA','TOGO','TUNISIA','UGANDA','ZAMBIA','ZIMBABWE']);
  ELSIF territory_key = '@region:north america' THEN
    RETURN country_key = ANY(ARRAY['ANTIGUAANDBARBUDA','BAHAMAS','BARBADOS','BELIZE','CA','COSTARICA','CUBA','DOMINICA','DOMINICANREPUBLIC','ELSALVADOR','GRENADA','GUATEMALA','HAITI','HONDURAS','JAMAICA','MEXICO','NICARAGUA','PANAMA','SAINTKITTSANDNEVIS','SAINTLUCIA','SAINTVINCENTANDTHEGRENADINES','TRINIDADANDTOBAGO','US']);
  ELSIF territory_key = '@region:south america' THEN
    RETURN country_key = ANY(ARRAY['ARGENTINA','BOLIVIA','BRAZIL','CHILE','COLOMBIA','ECUADOR','GUYANA','PARAGUAY','PERU','SURINAME','URUGUAY','VENEZUELA']);
  ELSIF territory_key = '@region:oceania' THEN
    RETURN country_key = ANY(ARRAY['AUSTRALIA','FIJI','KIRIBATI','MARSHALLISLANDS','MICRONESIA','NAURU','NEWZEALAND','PALAU','PAPUANEWGUINEA','SAMOA','SOLOMONISLANDS','TONGA','TUVALU','VANUATU']);
  END IF;
  RETURN FALSE;
END $$;
